import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, active, seq)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            o = book.get(oid)
            if o is None or (not o['active']) or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    def do_match(side, price, qty, order_type):
        # side: side of incoming order
        # returns remaining qty
        opp_heap = sell_heap if side == 'buy' else buy_heap
        while qty > 0:
            top = clean_top(opp_heap)
            if top is None:
                break
            oid = top[2]
            o = book[oid]
            resting_price = o['price']
            if order_type != 'market':
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break
            trade_qty = min(qty, o['qty'])
            if side == 'buy':
                buy_id = None  # incoming buy id set outside
            # record trade later, need incoming id passed via closure variables
            trade_qty_used = trade_qty
            # apply
            o['qty'] -= trade_qty
            qty -= trade_qty
            if o['qty'] == 0:
                o['active'] = False
                heapq.heappop(opp_heap)
            yield (oid, resting_price, trade_qty_used)
        return

    for entry in orders:
        cmd = entry[0]
        if cmd == 'cancel':
            oid = entry[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if cmd == 'limit':
            _, oid, side, price, qty = entry
            order_type = 'limit'
        elif cmd == 'ioc':
            _, oid, side, price, qty = entry
            order_type = 'ioc'
        elif cmd == 'market':
            _, oid, side, qty = entry
            price = None
            order_type = 'market'
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = clean_top(opp_heap)
            if top is None:
                break
            resting_oid = top[2]
            o = book[resting_oid]
            resting_price = o['price']
            if order_type != 'market':
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break
            trade_qty = min(remaining, o['qty'])
            o['qty'] -= trade_qty
            remaining -= trade_qty

            if side == 'buy':
                buy_id = oid
                sell_id = resting_oid
            else:
                buy_id = resting_oid
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            if o['qty'] == 0:
                o['active'] = False
                heapq.heappop(opp_heap)

        if order_type == 'limit' and remaining > 0:
            book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'active': True,
                'seq': seq_counter
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
        else:
            # if limit order fully filled, still record it in book as inactive/filled (optional)
            if order_type == 'limit':
                book[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'active': False,
                    'seq': seq_counter
                }
            # ioc/market remainder discarded, no book entry needed but store for cancel safety
            else:
                book[oid] = {
                    'side': side,
                    'price': price if price is not None else 0,
                    'qty': 0,
                    'active': False,
                    'seq': seq_counter
                }

        seq_counter += 1

    return trades

